// Validation des paramètres
const input = $input.first().json;
const body = input.body || input;

const items = Array.isArray(body.items) ? body.items : [];
const apiKey = body.api_key || '';
const model = body.model || '';
const maxTokens = body.max_tokens || 8192;
const projectId = body.project_id || '';
const callbackChannelId = body.callback_channel_id || null;

const errors = [];
if (items.length === 0) errors.push('Le champ "items" (tableau non vide) est requis');
if (!apiKey) errors.push('Le champ "api_key" (Anthropic) est requis');
if (!model) errors.push('Le champ "model" est requis');
if (!projectId) errors.push('Le champ "project_id" est requis');
items.forEach((it, i) => {
  if (!it.commentary_id) errors.push('items[' + i + '].commentary_id est requis');
  if (!it.segment_id) errors.push('items[' + i + '].segment_id est requis');
  if (!it.segmentText) errors.push('items[' + i + '].segmentText est requis');
});

return [{
  json: {
    valid: errors.length === 0,
    errors: errors,
    items: items,
    api_key: apiKey,
    model: model,
    max_tokens: maxTokens,
    project_id: projectId,
    callback_channel_id: callbackChannelId
  }
}];

const body = $('Validate Input').first().json;
const jobId = $('Create Job').first().json.job_id || $('Create Job').first().json.id;
const model = body.model;                     // du payload, verbatim
const maxTokens = body.max_tokens || 8192;    // headroom : commentaire entier non chunké
const requests = body.items.map(it => {
  const commentator = it.metadata && it.metadata.commentator ? ' - ' + it.metadata.commentator : '';
  const prompt = 'Tu es un expert en textes talmudiques. Le texte source est en ' + it.sourceLangName +
    '. Traduis en ' + it.targetLangName + '.\n\nContexte: ' + it.traite + ' ' + it.page + commentator +
    '\n\nTexte à traduire:\n' + it.segmentText + '\n\nRéponds UNIQUEMENT avec la traduction.';
  return { custom_id: String(it.commentary_id), params: { model, max_tokens: maxTokens, messages: [{ role: 'user', content: prompt }] } };
});
// carte custom_id -> segment_id, pour la sauvegarde côté callback
const commentary_map = {};
body.items.forEach(it => { commentary_map[String(it.commentary_id)] = { segment_id: it.segment_id }; });
return {
  api_key: body.api_key,
  callback_url: $env.N8N_WEBHOOK_URL + '/webhook/torah-translation-callback',
  metadata: { multi: true, job_id: jobId, project_id: body.project_id,
              target_lang: body.items[0] && body.items[0].targetLangName,
              callback_channel_id: body.callback_channel_id, commentary_map },
  requests
};

// Le job doit exister AVANT de soumettre : sans lui, le lot part chez Anthropic
// et devient introuvable — travail lancé, facturé, intraçable.
// Create Job est désormais en continueErrorOutput, donc arriver ici signifie
// qu'il a réussi. On vérifie quand même, parce qu'un id absent produirait une
// réponse d'apparence normale : JSON.stringify omet silencieusement les undefined.
const job = $('Create Job').first().json;
const jobId = job.job_id || job.id || null;
// $('Submit'), pas $input : depuis l'insertion de Set Processing entre les deux,
// $json porte la réponse du PATCH de statut — batch_id, redis_channel et
// correlation_id y sont absents, et le lot redevenait introuvable alors même
// qu'il tournait. Un nœud inséré déplace la source de tout ce qui le suit.
const soumission = $('Submit').first().json || {};
const count = $('Build Requests').first().json.requests.length;

if (!jobId) {
  return [{ json: {
    success: false,
    batch: true,
    count: count,
    batch_id: soumission.batch_id || null,
    error: {
      code: 502,
      message: 'Lot soumis mais job non créé : le suivi est impossible. Conserver le batch_id.',
      status: 'JOB_CREATION_FAILED'
    }
  } }];
}

return [{
  json: {
    success: true,
    job_id: jobId,
    batch: true,
    count: count,
    // Remontés pour que le lot reste retrouvable même si le suivi par job casse.
    batch_id: soumission.batch_id || null,
    redis_channel: soumission.redis_channel || null,
    correlation_id: soumission.correlation_id || null
  }
}];

// Construire la réponse d'erreur de validation
const input = $input.first().json;

return [{
  json: {
    success: false,
    error: {
      code: 400,
      message: input.errors.join(', '),
      status: 'BAD_REQUEST'
    }
  }
}];

// Création du job impossible : on n'a pas soumis le lot, donc rien n'est engagé.
// Refuser franchement vaut mieux que dépenser sans pouvoir suivre.
const e = $input.first().json || {};
const brut = String(e?.error?.message || e?.message || '');
return [{ json: {
  success: false,
  error: {
    code: 502,
    message: 'Création du job impossible — lot NON soumis, aucun coût engagé. ' + brut.slice(0, 200),
    status: 'JOB_CREATION_FAILED'
  }
} }];

// Le lot n'est pas parti : le job vient d'être marqué failed, et l'appelant
// doit le savoir tout de suite plutôt que de poller un job qui n'avancera
// jamais. Sans cette branche, Set Processing s'exécutait quand même et le
// job affichait « processing » alors que rien n'avait été soumis.
const e = $('Submit').first().json || {};
const brut = String(e?.error?.message || e?.message || '');
return [{ json: {
  success: false,
  job_id: $('Create Job').first().json.job_id || $('Create Job').first().json.id || null,
  batch: true,
  error: {
    code: 502,
    message: 'Soumission du lot impossible — aucune requête envoyée, job marqué failed. ' + brut.slice(0, 200),
    status: 'BATCH_SUBMIT_FAILED'
  }
} }];
